        # 寻找最右侧下降点 idx，使得 p[idx] > p[idx+1]
        idx = -1
        for i in range(n - 2, -1, -1):
            if p[i] > p[i + 1]:
                idx = i
                break

        # 如果没有下降点，排列已全增，无解
        if idx < 0:
            print("NO")
            continue

        # 构造 q 并局部交换
        q = p.copy()
        if idx <= n - 3:
            # 交换 q[idx] 与 q[idx+2]
            q[idx], q[idx + 2] = q[idx + 2], q[idx]
        else:
            # idx == n-2，交换 q[idx-1] 与 q[idx]
            q[idx - 1], q[idx] = q[idx], q[idx - 1]

        # 输出结果
        print("YES")
        print(*q)

